        "desc": "习惯在网上跟过得更好的人比的人，往往情绪更差、自尊更低。把 Facebook 停用四周的人，幸福感小幅提高，但对时事的了解也掉了一截。把三个社交平台各限到每天 10 分钟的人，三周后孤独和抑郁都降了下来。\n成本：不花钱。给应用设限时，或者把账号停掉，都是几分钟的事。难的是之后不再打开，要长期对抗惯性。　证据等级：A"
