        "desc": "登记本身不花钱，注册费 2015 年起就停征了。要交的材料只有五项：申请书、身份或资格证明、经营场所文件、章程或合伙协议（个体户不用交），加上法规另外点名要的。材料齐了当场发执照，当场发不了的 3 个工作日内办完。被收的那笔钱多半是代办跑腿费。\n成本：登记这一步不花钱。企业和个体工商户的注册登记费，从 2015 年 1 月 1 日起就停收了。自己在当地政务服务网上办，或者去政务大厅办，一次几个小时。刻公章、请人代记账、租一个注册地址（地址托管），是在市场上买服务，不是政府收的费。　证据等级：A"
