    "subCategory": "消费决策",
    "summary": "口径：金钱。租房最容易亏钱的地方是押金和中介。买房最费钱的地方是贷款利息，还有卖方知道、你不知道的那些事。",
    "brief": "口径：金钱。租房最容易亏钱的地方是押金和中介。",
