        "desc": "病情稳定、吃的药也没换的人，在社区卫生服务中心一次能开够 12 周的药。省掉每月往返大医院排队挂号的半天。在同一个参保地里，住基层医院的报销比例通常还比上一级医院高十个百分点左右。\n成本：不花钱。去社区卫生服务中心问一句能不能开长期处方，一句话的事。　证据等级：A"
