        "desc": "痛风要长期吃降尿酸药，把尿酸压到 360 µmol/L 以下，不能只在疼的时候吃止痛药。由护士按化验结果帮着调药量的病人，两年后 95% 达标，照常看病的只有 30%。达标之后也不能停药。靠忌口降不到这条线，戒酒也只低 1.6 mg/dL。\n成本：别嘌醇每月几元到几十元。刚开始每几周查一次血尿酸来调药量，稳定之后每几个月查一次。头 3 到 6 个月还要同时吃一种预防发作的药。难在不疼的时候也得一直吃下去。　证据等级：A"
