    "summary": "口径：金钱。本节只讲手续怎么办、钱怎么拿，包括人刚走时先做什么、哪些费用有清单可以对。还有哪些账户里的钱能取回来，哪些事近亲属有权出面办。前五条按事情发生的先后排，依次是现场、死亡证明、遗体和火化、对死因有异议怎么办、销户。后面几条按性价比排。老人生前该做的安排，比如意定监护、遗嘱、账户，见第 17 节。因工死亡的三笔待遇见第 19 节。",
    "brief": "口径：金钱。本节只讲手续怎么办、钱怎么拿，包括人刚走时先做什么、哪些费用有清单可…",
