        "title": "死者的账号和个人信息，近亲属可以要求查阅、复制、更正、删除",
        "desc": "人走以后，近亲属为了自己的合法正当利益，可以要求平台查阅、复制、更正、删除死者的个人信息。平台要是拒绝，得说明理由。你也可以去法院起诉。有一个例外：他生前另有安排的，比如设过账号继承人、留下过明确意愿，按他的安排来。\n成本：不花钱。平台不配合，才需要去投诉或者起诉。　证据等级：A"
