    "title": "做一个网站或平台：资质、备案和服务器",
    "categoryId": "work",
    "subCategory": "效率提升",
    "summary": "你想做一个网站或者 App。本节回答四件事：它在法律上算哪种生意，要办哪张证，服务器放在哪里，用户在上面发的东西和收的钱谁来负责。口径是人身自由与金钱。条目的顺序是：先写会坐牢的，再写要先办证的，然后是平台每天都要做的事，最后一条是选服务器的经验，那条只能给判断、给不出数字。你是受雇的技术人员，红线见第 11 节。公司怎么注册、怎么报税，见第 12 节，本节不重复。各类证的对照表和选服务器的决策表。",
