        "desc": "休学有正式制度。父母或其他监护人提出申请，学校确认后报上级核准。一次最长 1 年，期满还要休就重新申请。休学期间学校要给孩子保留学籍，复学时回来接着上。具体办法各省定，问学校教务处或当地教育局。\n成本：不花钱。由父母或其他法定监护人向学校提出申请。难在要先接受孩子停一段时间。　证据等级：B"
